const VD={id:'vodun',short:'Vodun Days',title:'Vodun Days 2027 · Ouidah',start:'2027-01-02',end:'2027-01-09',cover:'https://www.gouv.bj/upload/images/albums/802360682082001736762573.jpg',opts:[{n:{fr:'Découverte · 1 journée',en:'Discovery · 1 day'},d:{fr:'Accompagnement AFA TOURS sur une journée, selon programme et disponibilité.',en:'AFA TOURS guidance for one day, subject to programme and availability.'},p:25000},{n:{fr:'Immersion · 2 jours',en:'Immersion · 2 days'},d:{fr:'Accompagnement AFA TOURS sur deux journées.',en:'AFA TOURS guidance over two days.'},p:45000},{n:{fr:'Expérience complète · 7 jours',en:'Full experience · 7 days'},d:{fr:'Formule d’accompagnement sur sept jours pendant le festival.',en:'Seven-day guidance package during the festival.'},p:120000},{n:{fr:'VIP · 7 jours',en:'VIP · 7 days'},d:{fr:'Formule premium sur sept jours, prestations à confirmer dans le devis.',en:'Premium seven-day package, services confirmed in the quote.'},p:200000}]};
const L={fr:{pg:'par groupe',vsT:'Découvrir la culture vodun',vsS:'Masques, gardiens et ancêtres : des rencontres avec ceux qui transmettent la tradition.',act1:'activité',actN:'activités',grp:'Groupe (7 pers. et +)',a8:'Oui. Notre équipe vous répond en français et en anglais, de votre premier message à votre retour.',q8:'Parlez-vous anglais ?',a7:'Oui. Itinéraires connus, véhicules avec chauffeur, sites visités avec leurs gardiens, horaires annoncés à l’avance, et une équipe joignable par WhatsApp ou par téléphone pendant tout votre séjour.',q7:'Mon séjour est-il sûr ?',a6:'Oui. Le Bénin reste notre destination principale, mais nous organisons aussi des voyages au Togo, au Ghana, en Côte d’Ivoire et dans d’autres pays. Dites-nous où vous voulez aller : nous construisons le programme avec vous.',q6:'Voyagez-vous aussi hors du Bénin ?',a5:'Par Mobile Money, par carte bancaire ou en espèces à l’agence. Le montant est annoncé en FCFA avant le départ, avec une estimation dans votre monnaie.',q5:'Comment payer ?',fx:'Prix en FCFA (monnaie de paiement). Les autres monnaies sont indicatives et incluent une marge de 7 % pour couvrir les variations de change.',fxl:'(taux du jour)',fxs:'(taux indicatif)',home:'Accueil',nav1:'Circuits',nav2:'Événements',nav3:'Notre approche',nav4:'Galerie',nav5:'Avis',nav6:'Contact',menu:'Menu',close:'Fermer',sel:'Ma sélection',quote:'Demander un devis',ann:'Vodun Days 2027 à Ouidah, du 2 au 9 janvier.',annl:'Voir les formules',heroT:'Découvrez l’Afrique à travers le Bénin',heroS:'Des circuits guidés par des Béninois, de Porto-Novo à Grand-Popo. Une demi-journée ou trois semaines : choisissez, réservez, nous organisons le reste, transport compris.',see:'Voir les circuits',fd:'Destination',ft:'Thème',fh:'Durée',all:'Toutes',allm:'Tous',h3:'Jusqu’à 3 h',h4:'Jusqu’à 4 h',go:'Trouver mon circuit',t1:'12 destinations',t1s:'de Porto-Novo à Grand-Popo',t2:'2 à 4 h',t2s:'pour la plupart des sorties',t3:'Guides béninois',t3s:'qui connaissent les lieux',t4:'Sur mesure',t4s:'circuit conçu avec vous',t5:'Réponse sous 24 h',t5s:'par WhatsApp ou e-mail',cE:'Nos circuits',cT:'Le Bénin qu’on ne raconte pas : vivez-le avec nous',cD:'Filtrez par thème et par durée, ouvrez un circuit pour voir les étapes, puis ajoutez-le à votre demande.',search:'Rechercher : Ouidah, pirogue, safari…',sort:'Trier',s0:'Recommandé',s1:'Durée',s2:'Prix croissant',s3:'Destination (A–Z)',priced:'Prix affiché',map:'Carte',list:'Liste',cnt1:' circuit',cntn:' circuits',none:'Aucun circuit ne correspond.',reset:'Réinitialiser',detail:'Voir le détail',add:'Réserver ce circuit',added:'✓ Ajouté · Finaliser',rem:'Retirer de ma demande',onreq:'Tarif sur demande',pp:'par personne',from:'À partir de',stops:'Ce que vous ferez',mapnote:'Carte schématique, positions approximatives.',aE:'Événements',aT:'Vodun Days 2027 : Ouidah vibre du 2 au 9 janvier',aD:'Du 2 au 9 janvier, Ouidah devient le cœur battant du monde vodun : cérémonies, danses, masques, rencontres. Le compte à rebours est lancé et nos places d’accompagnement sont limitées. Réservez votre formule avant qu’elle ne soit complète. Billets officiels et hébergement non inclus.',days:'jours',hrs:'heures',min:'min',started:'Le festival est en cours',ended:'Édition terminée',choose:'Choisissez votre formule',appE:'Notre approche',appT:'Le Bénin se comprend en marchant, en écoutant et en partageant un repas.',v1:'Locale',v1d:'Des guides béninois, des artisans et des familles qui racontent leur propre histoire.',v2:'Sur mesure',v2d:'Une demande particulière ? Nous construisons le circuit avec vous, jusqu’au budget.',v3:'Simple',v3d:'Sans compte.',appL:'AFA TOURS, Afrique Authentique Innovant, est une agence béninoise engagée dans la gestion et la préservation du patrimoine culturel, matériel et immatériel. Nous sommes une équipe de jeunes passionnés, professionnels et dynamiques. Notre slogan : découvrir l’Afrique à travers le Bénin.',ap1:'Gardiens du patrimoine, matériel et immatériel',ap1d:'Palais, musées, mosquée afro-brésilienne, sites sacrés : nous valorisons le patrimoine bâti. Cultes vodun, cérémonies, chants, danses, savoir-faire, langues : nous protégeons aussi ce qui se transmet de voix en voix. Chaque visite est pensée pour respecter ces lieux et ces traditions, et pour les transmettre.',ap2:'Des Béninois qui vous reçoivent',ap2d:'Guides, artisans, cuisiniers, familles : chaque étape se vit avec des personnes du lieu qui racontent leur propre histoire. Votre séjour fait vivre ceux qui vous accueillent.',ap3:'Des experts à chaque niveau',ap3d:'Nous sommes une équipe de jeunes passionnés, professionnels et dynamiques. Chaque circuit est conçu par nos experts et nos gestionnaires de patrimoine, puis accompagné sur le terrain par des guides compétents, des chauffeurs expérimentés, des hôteliers et des restaurateurs choisis pour leur sérieux.',ap4:'Votre sécurité avant tout',ap4d:'Itinéraires connus, véhicules avec chauffeur, sites visités avec leurs gardiens, horaires et points de rendez-vous annoncés à l’avance. Notre équipe reste joignable pendant tout votre séjour par WhatsApp ou par téléphone.',ap5:'Un voyage agréable et inoubliable',ap5d:'Nous sommes là pour vous satisfaire. Rythme, repas, hébergement, transport : chaque détail est réglé pour votre confort et votre plaisir. Vous repartez avec des souvenirs et des rencontres, pas avec des soucis.',ap6:'Sur mesure, du Bénin vers l’Afrique',ap6d:'Le Bénin reste notre destination principale, et du Bénin on peut aller loin : nous organisons aussi des voyages au Togo, au Ghana, en Côte d’Ivoire et dans d’autres pays. Une demande particulière ? Nous construisons le séjour avec vous : circuits, hébergement, transport, durée et budget.',ap7:'Une équipe à votre écoute, des prix clairs',ap7d:'Une même équipe, en français ou en anglais, de votre premier message à votre retour. Les prix sont annoncés en FCFA avant le départ, avec une estimation dans votre monnaie. Paiement par Mobile Money, carte bancaire ou en espèces à l’agence.',appC1:'Composer mon séjour',appC2:'Demander un devis',pE:'Avant de partir',pT:'Vos questions',q1:'Combien de temps dure une sortie ?',a1:'De deux à quatre heures pour la plupart des circuits. Nous pouvons aussi vous composer un séjour de plusieurs jours, jusqu’à trois semaines.',q2:'Quels sont les tarifs ?',a2:'Les tarifs sont en francs CFA, par personne, avec un affichage en euros possible. Pour les circuits sur devis, nous calculons le tarif avec vous avant le départ, sans surprise.',q3:'Comment réserver ?',a3:'Ajoutez vos circuits, envoyez la demande : nous répondons par e-mail ou WhatsApp avec les horaires et le point de rendez-vous. Aucun paiement en ligne n’est demandé sur le site.',q4:'Quelles formalités pour entrer au Bénin ?',a4:'La plupart des voyageurs ont besoin d’un passeport valide au moins six mois après leur arrivée et d’un e-visa à demander en ligne avant le départ, sur le site officiel evisa.bj. Les ressortissants de la CEDEAO sont dispensés de visa. Le vaccin contre la fièvre jaune est recommandé et peut être demandé selon votre provenance : vérifiez les règles en vigueur avant de partir. Écrivez-nous votre nationalité : nous vous indiquons les démarches.',gE:'Galerie',gT:'Nos voyages en images',gD:'Parcourez nos voyages en images : le prochain est peut-être le vôtre.',shE:'Vos souvenirs',shT:'Partagez vos photos de voyage',shD:'Envoyez une photo ou une courte vidéo. Chaque fichier est vérifié avant publication.',files:'Photos et vidéos',fileh:'JPG, PNG, WebP, MP4 ou WebM. Plusieurs fichiers possibles.',caption:'Légende',cons1:'Publier ce contenu sur le site après validation ? *',cons2:'L’utiliser dans nos communications ? *',yes:'Oui',no:'Non',send:'Envoyer',rvE:'Avis des voyageurs',rvT:'Leurs mots, leurs voyages',rvEmpty:'Aucun avis publié pour l’instant. Vous avez voyagé avec nous ? Racontez-nous votre expérience, elle sera lue puis publiée.',rvW:'Écrire un avis',rvH:'Racontez votre voyage',rvB:'Votre avis',rvN:'Votre nom',rvM:'Votre email (non publié)',rvS:'Publier mon avis',rvOk:'Merci. Votre avis sera publié après vérification par notre équipe.',noav:'Aucune note',qE:'Votre demande',qT:'Parlons de votre voyage',qD:'Dites-nous ce que vous aimeriez voir et quand. Nous répondons avec une proposition claire.',qS:'Circuits choisis',qNone:'Aucun pour l’instant. Ajoutez-en depuis la liste.',qGo:'Choisir un circuit',name:'Nom',contact:'Email ou WhatsApp',date:'Date souhaitée',pax:'Voyageurs',msg:'Votre projet',est:'Estimation',estn:'Indicatif, confirmé par notre équipe.',onq:'sur devis',sendq:'Envoyer ma demande',wa:'Écrire sur WhatsApp',okq:'Maquette : votre demande serait envoyée ici.',emp:'Ajoutez d’abord un circuit, ou décrivez votre projet.',ft1:'Explorer',ft2:'Nous joindre',foot:'Découvrez l’Afrique à travers le Bénin.',demo:'Maquette : aucune donnée n’est envoyée.',priv:'Confidentialité',team:'Espace équipe',catn:'Les prix sont en francs CFA par personne. Horaires et point de rendez-vous confirmés après votre demande.',next:'Suivant',prev:'Précédent',pause:'Pause',play:'Lecture'},
en:{pg:'per group',vsT:'Discover vodun culture',vsS:'Masks, guardians and ancestors: meet those who pass on the tradition.',act1:'activity',actN:'activities',grp:'Group (7+ people)',a8:'Yes. Our team answers in French and in English, from your first message to your return home.',q8:'Do you speak English?',a7:'Yes. Familiar routes, vehicles with a driver, sites visited with their custodians, schedules announced in advance, and a team reachable by WhatsApp or phone throughout your stay.',q7:'Is my trip safe?',a6:'Yes. Benin remains our main destination, but we also organize trips to Togo, Ghana, Côte d’Ivoire and other countries. Tell us where you want to go and we will build the programme with you.',q6:'Do you also travel outside Benin?',a5:'By Mobile Money, bank card or in cash at the agency. The amount is announced in FCFA before departure, with an estimate in your currency.',q5:'How do I pay?',fx:'Prices in FCFA (payment currency). Other currencies are indicative and include a 7% margin to cover exchange-rate variations.',fxl:'(live rate)',fxs:'(indicative rate)',home:'Home',nav1:'Tours',nav2:'Events',nav3:'Our approach',nav4:'Gallery',nav5:'Reviews',nav6:'Contact',menu:'Menu',close:'Close',sel:'My selection',quote:'Request a quote',ann:'Vodun Days 2027 in Ouidah, 2–9 January.',annl:'See packages',heroT:'Discover Africa through Benin',heroS:'Tours led by Beninese guides, from Porto-Novo to Grand-Popo. From half a day to three weeks: choose, book, and we organise the rest, transport included.',see:'See the tours',fd:'Destination',ft:'Theme',fh:'Duration',all:'All',allm:'All',h3:'Up to 3 h',h4:'Up to 4 h',go:'Find my tour',t1:'12 destinations',t1s:'from Porto-Novo to Grand-Popo',t2:'2 to 4 h',t2s:'for most outings',t3:'Beninese guides',t3s:'who know the places',t4:'Tailor-made',t4s:'tours built around you',t5:'Reply within 24 h',t5s:'by WhatsApp or email',cE:'Our tours',cT:'The Benin nobody tells you about: live it with us',cD:'Filter by theme and duration, open a tour to see the stops, then add it to your request.',search:'Search: Ouidah, pirogue, safari…',sort:'Sort',s0:'Recommended',s1:'Duration',s2:'Price, low to high',s3:'Destination (A–Z)',priced:'Price shown',map:'Map',list:'List',cnt1:' tour',cntn:' tours',none:'No tour matches.',reset:'Reset',detail:'See details',add:'Book this tour',added:'✓ Added · Finish',rem:'Remove from my request',onreq:'Price on request',pp:'per person',from:'From',stops:'What you will do',mapnote:'Schematic map, approximate positions.',aE:'Events',aT:'Vodun Days 2027: Ouidah comes alive from 2 to 9 January',aD:'From 2 to 9 January, Ouidah becomes the beating heart of the vodun world: ceremonies, dances, masks, encounters. The countdown has started and our guided places are limited. Book your package before it is full. Official tickets and lodging not included.',days:'days',hrs:'hours',min:'min',started:'The festival is under way',ended:'Edition over',choose:'Choose your package',appE:'Our approach',appT:'Benin is understood by walking, listening and sharing a meal.',v1:'Local',v1d:'Beninese guides, artisans and families telling their own story.',v2:'Tailor-made',v2d:'A special request? We build the tour with you, down to the budget.',v3:'Simple',v3d:'No account needed.',appL:'AFA TOURS, Afrique Authentique Innovant, is a Beninese agency dedicated to managing and preserving cultural heritage, both tangible and intangible. We are a team of passionate, professional and dynamic young people. Our slogan: discover Africa through Benin.',ap1:'Guardians of heritage, tangible and intangible',ap1d:'Palaces, museums, the Afro-Brazilian mosque, sacred sites: we celebrate built heritage. Vodun cults, ceremonies, songs, dances, crafts, languages: we also protect what is passed down from voice to voice. Every visit is designed to respect these places and traditions, and to pass them on.',ap2:'Beninese hosts who welcome you',ap2d:'Guides, artisans, cooks, families: every stop is shared with local people who tell their own story. Your stay supports the people who host you.',ap3:'Experts at every level',ap3d:'We are a team of passionate, professional and dynamic young people. Each tour is designed by our experts and heritage managers, then led on the ground by skilled guides, experienced drivers, and hoteliers and restaurateurs chosen for their reliability.',ap4:'Your safety comes first',ap4d:'Familiar routes, vehicles with a driver, sites visited with their custodians, schedules and meeting points announced in advance. Our team stays reachable throughout your stay by WhatsApp or phone.',ap5:'An enjoyable, unforgettable trip',ap5d:'We are here to make you happy. Pace, meals, accommodation, transport: every detail is arranged for your comfort and enjoyment. You go home with memories and encounters, not worries.',ap6:'Tailor-made, from Benin to the rest of Africa',ap6d:'Benin remains our main destination, and from Benin you can go far: we also organize trips to Togo, Ghana, Côte d’Ivoire and other countries. A special request? We build the stay with you: tours, accommodation, transport, length and budget.',ap7:'A team at your service, clear prices',ap7d:'The same team, in French or English, from your first message to your return home. Prices are announced in FCFA before departure, with an estimate in your currency. Pay by Mobile Money, bank card or in cash at the agency.',appC1:'Plan my stay',appC2:'Request a quote',pE:'Before you go',pT:'Your questions',q1:'How long is an outing?',a1:'Two to four hours for most tours. We can also build a stay of several days, up to three weeks.',q2:'What are the prices?',a2:'Prices are in CFA francs per person, with a euro display available. For tours on quote, we work out the price with you before departure, with no surprises.',q3:'How do I book?',a3:'Add your tours and send the request: we reply by email or WhatsApp with times and meeting point. No online payment is requested on the site.',q4:'What are the entry requirements for Benin?',a4:'Most travellers need a passport valid for at least six months after arrival and an e-visa requested online before departure on the official site evisa.bj. ECOWAS citizens do not need a visa. A yellow fever vaccination is recommended and may be requested depending on where you travel from: check the current rules before you leave. Tell us your nationality and we will explain the steps.',gE:'Gallery',gT:'Our trips in pictures',gD:'Browse our trips in pictures: the next one could be yours.',shE:'Your memories',shT:'Share your travel photos',shD:'Send a photo or a short video. Every file is checked before publication.',files:'Photos and videos',fileh:'JPG, PNG, WebP, MP4 or WebM. Several files allowed.',caption:'Caption',cons1:'Publish this on the site after approval? *',cons2:'Use it in our communications? *',yes:'Yes',no:'No',send:'Send',rvE:'Traveller reviews',rvT:'Their words, their journeys',rvEmpty:'No reviews published yet. Travelled with us? Tell us about it, it will be read then published.',rvW:'Write a review',rvH:'Tell us about your trip',rvB:'Your review',rvN:'Your name',rvM:'Your email (not published)',rvS:'Publish my review',rvOk:'Thank you. Your review will be published after our team checks it.',noav:'No rating',qE:'Your request',qT:'Let’s talk about your trip',qD:'Tell us what you would like to see and when. We reply with a clear proposal.',qS:'Chosen tours',qNone:'None yet. Add some from the list.',qGo:'Choose a tour',name:'Name',contact:'Email or WhatsApp',date:'Preferred date',pax:'Travellers',msg:'Your project',est:'Estimate',estn:'Indicative, confirmed by our team.',onq:'on quote',sendq:'Send my request',wa:'Write on WhatsApp',okq:'Mockup: your request would be sent here.',emp:'Add a tour first, or describe your project.',ft1:'Explore',ft2:'Contact us',foot:'Discover Africa through Benin.',demo:'Mockup: no data is sent.',priv:'Privacy',team:'Team area',catn:'Prices are in CFA francs per person. Times and meeting point confirmed after your request.',next:'Next',prev:'Previous',pause:'Pause',play:'Play'}};
let lang='fr',cur='XOF';const t=k=>(L[lang][k]??L.fr[k]??k);
const $=(s,r=document)=>r.querySelector(s),$$=(s,r=document)=>[...r.querySelectorAll(s)];
const esc=s=>String(s).replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
const loc=()=>lang==='fr'?'fr-FR':'en-GB';
