function tick(){const now=new Date(),s=new Date(VD.start+'T00:00:00'),e=new Date(VD.end+'T23:59:59'),el=$('#count');if(!el)return;if(now>e){el.innerHTML='<div style="min-width:0;padding:12px 18px"><b style="font-size:1.1rem">'+t('ended')+'</b></div>';return}if(now>=s){el.innerHTML='<div style="min-width:0;padding:12px 18px"><b style="font-size:1.1rem">'+t('started')+'</b></div>';return}const ms=s-now,d=Math.floor(ms/864e5),h=Math.floor(ms/36e5)%24,m=Math.floor(ms/6e4)%60,sc=Math.floor(ms/1e3)%60;el.innerHTML='<div><b>'+d+'</b>'+t('days')+'</div><div><b>'+h+'</b>'+t('hrs')+'</div><div><b>'+m+'</b>'+t('min')+'</div><div><b class="sx">'+String(sc).padStart(2,'0')+'</b>'+(lang==='en'?'sec':'sec')+'</div>'}
